import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        // Depth = number of open brackets around the integer; scan the JSON text directly.
        long total = 0, depth = 0;
        int i = 0;
        while (i < buf.length) {
            byte c = buf[i];
            if (c == '[') {
                depth++;
                i++;
            } else if (c == ']') {
                depth--;
                i++;
            } else if (c == '-' || (c >= '0' && c <= '9')) {
                boolean neg = c == '-';
                if (neg) i++;
                long v = 0;
                while (i < buf.length && buf[i] >= '0' && buf[i] <= '9') v = v * 10 + (buf[i++] - '0');
                total += (neg ? -v : v) * depth;
            } else i++;
        }
        System.out.println(total);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	// Depth = number of open brackets around the integer; scan the JSON text directly.
	var total, depth int64
	for i := 0; i < len(data); {
		c := data[i]
		switch {
		case c == '[':
			depth++
			i++
		case c == ']':
			depth--
			i++
		case c == '-' || (c >= '0' && c <= '9'):
			neg := c == '-'
			if neg {
				i++
			}
			var v int64
			for i < len(data) && data[i] >= '0' && data[i] <= '9' {
				v = v*10 + int64(data[i]-'0')
				i++
			}
			if neg {
				v = -v
			}
			total += v * depth
		default:
			i++
		}
	}
	fmt.Println(total)
}
